package cn.workbench;
import org.junit.jupiter.api.Test;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.context.ActiveProfiles;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.mock.web.MockHttpServletRequest;
import java.util.*;
import java.time.*;
import static org.assertj.core.api.Assertions.*;
import static cn.workbench.Records.map;
@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:handover;MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1","task.bootstrap-password=TestOnly-Synthetic12345","task.totp-key=AAECAwQFBgcICQoLDA0ODxAREhMUFRYXGBkaGxwdHh8="})
@org.springframework.test.context.TestExecutionListeners(value={org.springframework.test.context.support.DependencyInjectionTestExecutionListener.class,org.springframework.test.context.transaction.TransactionalTestExecutionListener.class},mergeMode=org.springframework.test.context.TestExecutionListeners.MergeMode.REPLACE_DEFAULTS)
@ActiveProfiles("test") @Transactional class OrganizationChangesTest {
 @Autowired Store db;@Autowired JdbcTemplate jdbc;@Autowired OrganizationController organizations;@Autowired OrganizationChangesController controller;@Autowired OrganizationChanges changes;@Autowired Policy policy;@Autowired Records records;@Autowired TaskService tasks;@Autowired Writes writes;
 @Test void expiredAndOnLeaveAppointmentsAreNotEffective(){jdbc.update("UPDATE user_scope SET valid_until=? WHERE id=3",java.sql.Timestamp.from(Instant.now().minusSeconds(60)));assertThat(db.scope(3,3)).isNull();jdbc.update("UPDATE user_scope SET valid_until=NULL,employment_status='ON_LEAVE' WHERE id=3");assertThat(db.scope(3,3)).isNull();}
 @Test void appointmentDefaultsRemainActiveAndEffective(){assertThat(jdbc.queryForMap("SELECT employment_status,appointment_type,version FROM user_scope WHERE id=3")).containsEntry("employment_status","ACTIVE").containsEntry("appointment_type","PRIMARY").containsEntry("version",0);assertThat(db.scope(3,3)).isNotNull();}

 MockHttpServletRequest request(String method,String path,long user,long scope){var q=new MockHttpServletRequest(method,"/api/v1"+path);q.getSession().setAttribute("uid",user);q.getSession().setAttribute("scopeId",scope);q.getSession().setAttribute("totpAt",System.currentTimeMillis());q.addHeader("Idempotency-Key",UUID.randomUUID().toString());return q;}
 Map<String,Object> data(Object response){return (Map<String,Object>)((Map<?,?>)response).get("data");}
 long grant(List<String> permissions){return Jsons.number(data(controller.delegate(map("delegateUserId",4,"permissions",permissions,"validFrom",Instant.now().minusSeconds(5).toString(),"validUntil",Instant.now().plusSeconds(3600).toString(),"reason","Synthetic delegation"),request("POST","/organization/delegations",3,3))).get("id"));}
 Map<String,Object> task(){var t=tasks.create(new Policy.Actor(2,"COMPANY_LEADER",1,null,2),map("title","Handover fixture","content","Synthetic only","companyId",1,"hostDeptId",3,"collaboratorDeptIds",List.of(),"deadline",Instant.now().plusSeconds(3600).toString()));tasks.taskAction(new Policy.Actor(2,"COMPANY_LEADER",1,null,2),Jsons.number(t.get("id")),"confirm-assign",Map.of());var s=records.children(Jsons.number(t.get("id")),"SUB_TASK").getFirst();tasks.subAction(new Policy.Actor(3,"DEPT_HEAD",1,3,3),Jsons.number(s.get("id")),"receive",Map.of());return records.get(Jsons.number(s.get("id")));}
 @Test void futureDisabledAndForeignOrganizationAppointmentsAreNotEffective(){jdbc.update("UPDATE user_scope SET valid_from=? WHERE id=3",java.sql.Timestamp.from(Instant.now().plusSeconds(300)));assertThat(db.scope(3,3)).isNull();jdbc.update("UPDATE user_scope SET valid_from=NULL WHERE id=3");jdbc.update("UPDATE company SET enabled=FALSE WHERE id=1");assertThat(db.scopes(3)).isEmpty();}
 @Test void delegationRequiresSameDepartmentAndCannotGrantUnknownPermissions(){assertThatThrownBy(()->controller.delegate(map("delegateUserId",5,"permissions",List.of("submit"),"validFrom",Instant.now().toString(),"validUntil",Instant.now().plusSeconds(300).toString(),"reason","test"),request("POST","/organization/delegations",3,3))).isInstanceOf(ApiException.class);assertThatThrownBy(()->grant(List.of("admin"))).isInstanceOf(ApiException.class);}
 @Test void delegationIsExplicitNarrowAndRevocationIsImmediate(){long id=grant(List.of("receive"));var q=request("POST","/organization/delegations/"+id+"/activate",4,4);assertThat(policy.actor(q).role()).isEqualTo("EMPLOYEE");controller.activate(id,q);q.setRequestURI("/api/v1/sub-tasks/100/receive");assertThat(policy.actor(q).role()).isEqualTo("DEPT_HEAD");assertThat(policy.actor(q).allows("submit")).isFalse();q.setRequestURI("/api/v1/kpi/scores");q.setMethod("GET");assertThatThrownBy(()->policy.actor(q)).isInstanceOf(ApiException.class);q.setRequestURI("/api/v1/tasks");controller.revoke(id,map("version",0,"reason","Synthetic revocation"),request("POST","/organization/delegations/"+id+"/revoke",3,3));assertThatThrownBy(()->policy.actor(q)).isInstanceOf(ApiException.class);controller.leave(q);assertThat(policy.actor(q).role()).isEqualTo("EMPLOYEE");}
 @Test void expiredGrantOrUnavailableDelegatorCannotBeUsed(){long id=grant(List.of("receive"));var q=request("GET","/tasks",4,4);q.getSession().setAttribute("delegationId",id);jdbc.update("UPDATE scope_delegation SET valid_until=? WHERE id=?",java.sql.Timestamp.from(Instant.now().minusSeconds(1)),id);assertThatThrownBy(()->policy.actor(q)).isInstanceOf(ApiException.class);jdbc.update("UPDATE scope_delegation SET valid_until=? WHERE id=?",java.sql.Timestamp.from(Instant.now().plusSeconds(3600)),id);jdbc.update("UPDATE user_scope SET employment_status='ON_LEAVE' WHERE id=3");assertThatThrownBy(()->policy.actor(q)).isInstanceOf(ApiException.class);}
 @Test void transferKeepsOriginalSnapshotAndWritesImmutableHistory(){var s=task();long sid=Jsons.number(s.get("id"));var head=new Policy.Actor(3,"DEPT_HEAD",1,3,3);tasks.subAction(head,sid,"assign",map("ownerId",4,"userIds",List.of(4)));s=records.get(sid);Object original=s.get("originalOwnerSnapshot");tasks.subAction(head,sid,"transfer",map("userId",3,"version",s.get("version"),"reason","Synthetic handover"));var now=records.get(sid);assertThat(now.get("originalOwnerSnapshot")).isEqualTo(original);assertThat(Jsons.number(now.get("ownerId"))).isEqualTo(3);assertThat(changes.query("SELECT * FROM task_handover WHERE sub_task_id=?",sid)).hasSize(1);assertThatThrownBy(()->tasks.subAction(head,sid,"assign",map("ownerId",4,"userIds",List.of(4),"version",now.get("version")))).isInstanceOf(ApiException.class);}
 @Test void handoverBatchRejectsForeignDepartmentWithoutEffects(){var s=task();long sid=Jsons.number(s.get("id"));assertThatThrownBy(()->controller.handover(map("items",List.of(map("subTaskId",sid,"userId",5,"version",s.get("version"))),"reason","Invalid target"),request("POST","/organization/handovers",3,3))).isInstanceOf(ApiException.class);assertThat(changes.query("SELECT * FROM task_handover WHERE sub_task_id=?",sid)).isEmpty();assertThat(records.get(sid).get("ownerId")).isNull();}
 @Test void appointmentUpdateNeedsFreshTotpAndPreservesOtherScopes(){var q=request("PUT","/organization/appointments/3",1,1);q.getSession().removeAttribute("totpAt");var body=map("version",0,"employmentStatus","LEFT","appointmentType","PRIMARY","enabled",false,"validFrom",null,"validUntil",null,"reason","Synthetic departure");assertThatThrownBy(()->controller.appointment(3,body,q)).isInstanceOf(ApiException.class);q.getSession().setAttribute("totpAt",System.currentTimeMillis());int before=Jsons.integer(db.user(3).get("sessionVersion"));controller.appointment(3,body,q);assertThat(db.scope(3,3)).isNull();assertThat(Jsons.integer(db.user(3).get("sessionVersion"))).isEqualTo(before+1);assertThat(changes.query("SELECT * FROM business_record WHERE kind='APPOINTMENT_CHANGE'")).hasSize(1);}
 @Test void delegatedContextCannotReplayAnotherAuthorizationContext(){long id=grant(List.of("receive"));var q=request("POST","/sub-tasks/1/receive",4,4);writes.run(q,Map.of(),()->map("example","original"));q.getSession().setAttribute("delegationId",id);assertThatThrownBy(()->writes.run(q,Map.of(),()->map("example","delegated"))).isInstanceOf(ApiException.class);}

 @Test void delegatedExecutionAuditsActualPersonAndGrant(){var sub=task();sub.put("status","PENDING_RECEIVE");records.save(sub);long grant=grant(List.of("receive"));var q=request("POST","/sub-tasks/"+sub.get("id")+"/receive",4,4);q.getSession().setAttribute("delegationId",grant);var actor=policy.actor(q);tasks.subAction(actor,Jsons.number(sub.get("id")),"receive",Map.of());var audit=changes.query("SELECT * FROM audit_event WHERE action='SUBTASK_RECEIVE' AND delegation_id=?",grant);assertThat(audit).hasSize(1);assertThat(Jsons.number(audit.getFirst().get("actorId"))).isEqualTo(4);assertThat(records.children(Jsons.number(sub.get("taskId")),"TIMELINE")).anySatisfy(event->{assertThat(event.get("action")).isEqualTo("SUBTASK_RECEIVE");assertThat(Jsons.number(event.get("actorId"))).isEqualTo(4);assertThat(Jsons.number(event.get("delegationId"))).isEqualTo(grant);});}
 @Test void scopedAdministratorCannotChangeSharedAccountEvenIfForeignAppointmentExpired(){var scope=map("userId",3,"role","EMPLOYEE","companyId",2,"deptId",5);db.insertScope(scope);jdbc.update("UPDATE user_scope SET valid_until=? WHERE id=?",java.sql.Timestamp.from(Instant.now().minusSeconds(30)),scope.get("id"));assertThatThrownBy(()->controller.appointment(3,map("version",0,"employmentStatus","LEFT","appointmentType","PRIMARY","enabled",false,"reason","Must reject"),request("PUT","/organization/appointments/3",1,1))).isInstanceOf(ApiException.class);assertThat(db.scope(3,3)).isNotNull();}
 @Test void delegatedAssignmentCannotSilentlyTransferWithoutTransferPermission(){var sub=task();var head=new Policy.Actor(3,"DEPT_HEAD",1,3,3);long sid=Jsons.number(sub.get("id"));tasks.subAction(head,sid,"assign",map("ownerId",4,"userIds",List.of(4)));long id=grant(List.of("assign"));var q=request("POST","/sub-tasks/"+sid+"/assign",4,4);q.getSession().setAttribute("delegationId",id);var actor=policy.actor(q);assertThatThrownBy(()->tasks.subAction(actor,sid,"assign",map("version",records.get(sid).get("version"),"ownerId",3,"userIds",List.of(3),"reason","Need transfer permission"))).isInstanceOf(ApiException.class);assertThat(Jsons.number(records.get(sid).get("ownerId"))).isEqualTo(4);}

 @Test void expiredForeignScopeCannotBypassAccountResetOrDisable(){var scope=map("userId",3,"role","EMPLOYEE","companyId",2,"deptId",5);db.insertScope(scope);jdbc.update("UPDATE user_scope SET valid_until=? WHERE id=?",java.sql.Timestamp.from(Instant.now().minusSeconds(30)),scope.get("id"));var q=request("PATCH","/admin/users/3",1,1);String before=String.valueOf(db.user(3).get("passwordHash"));assertThatThrownBy(()->organizations.edit("users",3,map("enabled",false,"password","SyntheticReset123456"),q)).isInstanceOf(ApiException.class);assertThat(db.user(3).get("enabled")).isEqualTo(true);assertThat(db.user(3).get("passwordHash")).isEqualTo(before);}
}
